import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-122: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short122', durationInSeconds: 30.3, fps: 30, width: 1080, height: 1920 };

const T = [secToFrame(4.7), secToFrame(7.0), secToFrame(12.9), secToFrame(15.6), secToFrame(16.8), secToFrame(19.5), secToFrame(23.2)];
const CTA = secToFrame(25.3);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short122: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'ASTRA $10 IN' }, { text: 'FABLE $10 IN', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={T[0]}>
        <CoverImage src="projects/short-122/cover.png" out={T[0] - 10} />
        <HookTitle hold onDark kicker="FLAGSHIP PRICING" lines={lines} />
      </FadeOut>
      <FadeOut at={T[1]}>
        <ToolCard name="GPT-6 Astra" tagline="OpenAI flagship." chip="$10 / $50" at={T[0] - 2}>
          <Panel>
            <Line k="input /1M" v="$10.00" />
            <Line k="output /1M" v="$50.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[2]}>
        <ToolCard name="Fable 5.1" tagline="Claude flagship." chip="$10 / $50" at={T[1] - 2}>
          <Panel>
            <Line k="input /1M" v="$10.00" />
            <Line k="output /1M" v="$50.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[3]}>
        <ToolCard name="A perfect tie" tagline="On the sticker." chip="=" at={T[2] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Astra" v="$10 / $50" />
            <Line k="Fable 5.1" v="$10 / $50" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[4]}>
        <ToolCard name="Check the cache" tagline="Where it splits." chip="CACHE" at={T[3] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Astra" v="?" />
            <Line k="Fable 5.1" v="?" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[5]}>
        <ToolCard name="Astra cache hit" tagline="Per 1M tokens." chip="$1.00" at={T[4] - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="cached input" v="$1.00" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[6]}>
        <ToolCard name="Fable 5.1 cache hit" tagline="Per 1M tokens." chip="$0.25" at={T[5] - 2}>
          <Panel>
            <Line k="cached input" v="$0.25" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="4x cheaper" tagline="If prompts repeat." chip="4X" at={T[6] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Astra" v="$1.00" bad />
            <Line k="Fable 5.1" v="$0.25" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-122/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="FLAGSHIP PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Same sticker. Different bill.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short122;
